import{b as o,O as t,g as a,j as c}from"./chunks/framework.DcaUmd3X.js";const u=JSON.parse('{"title":"魅力口才与演讲的艺术","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/art-of-speech/index.md","filePath":"读书感悟/电子书架/6.魅力口才与演讲的艺术.md","lastUpdated":1781614933000}'),l={name:"reading/digital/art-of-speech/index.md"};function r(_,e,p,d,i,n){return t(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="魅力口才与演讲的艺术" tabindex="-1">魅力口才与演讲的艺术 <a class="header-anchor" href="#魅力口才与演讲的艺术" aria-label="Permalink to &quot;魅力口才与演讲的艺术&quot;">​</a></h1><p><code>卡耐基</code> <code>沟通表达</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 公众演讲能力给你带来的领导能力，远比你能想象到的其他任何活动都更为神速。 政治家昌西·M．迪普曾说过：“凡有志于快速成就其事业且获得认可之人，没有任何其他技能比动人心弦的演讲能力更为高效。”</p></blockquote><blockquote><p>📌 后来，一名头脑冷静的老乡绅那一席话让我获益匪浅。他在无意间引述了威灵顿公爵的名言。当然，威灵顿公爵也是从别人那里引述过来。那句名言如是：‘无言别起身，言毕即坐下。’” 就克服紧张情绪这一点而言，那名“头脑冷静的老乡绅”本可以再向罗斯福进一言。他本可以补充道：“在面对自己的听众时，如果你能找点事儿做，譬如展示一件物品、在黑板上写点什么、在地图上指个位置、挪动一下桌子、打开窗户、翻动书本等，所有这些努力都有助于你摆脱演讲时的尴尬处境。”</p></blockquote><blockquote><p>📌 波兰著名的男高音歌唱家让·德雷兹克过去常说，当你气息充足时，那么你就“可以坐在上面”，紧张感也随之消失。 在任何历史时期，在世上任何地方，人类都崇尚勇气。因此，无论你内心深处如何波涛汹涌，你都应昂首挺胸、大步向前，站在台上岿然不动，同时展现出你对演讲的无限热爱。 挺直腰板，直视听众，然后信心十足地开始讲话，就好像他们人人都欠你钱似的。想象一下他们的确欠你钱。</p></blockquote><blockquote><p>📌 想象一下，台下的他们现在全都聚在你的跟前，恳请你把债务再宽限数日，这样的心理效果将对你的演讲大有裨益。 不要反复折腾衣扣，也不要拨弄手中的珠子，或者用手在身上挠来挠去。如果你必须得做一点儿紧张的动作，不妨把手背在身后，揉一揉手指头，这样也不会被人看见——或者转动一下双脚的趾头也行。 一般来说，演讲者不宜躲藏在摆设物之后。在前几次演讲时，如果身前有张桌子或者椅子——或者手心里握一枚硬币——好让你在紧张时有所倚靠，这或许能给你自己壮壮胆儿。</p></blockquote><blockquote><p>📌 泰迪·罗斯福继续写道：“这就是我所遵循的理论依据。一开始，我对什么东西都害怕过，大灰熊、‘烈’马以及枪手等，不过，通过上述方法的不断练习之后，我渐渐不再害怕。只要愿意这么做，绝大部分人都能达到同样的效果。” 只要你愿意，你也可以跟泰迪·罗斯福一样战胜恐惧。“战争中，”福煦元帅如是说道，“最好的防御就是进攻。”所以，向你的恐惧发起进攻吧。只要有机会，就凭着你的无畏去迎战它、打败它、征服它。</p></blockquote><blockquote><p>📌 从1912年以来，我每年都会听大约6000场演讲并做出点评。对我而言，这既是职责所在，也是乐趣使然。演讲者当中有大学生，也有成功商人和专业人士。要说这些经历让我感触最深的，那一定是：演讲前必须对自己打算讲的内容做到心中有数、胸有成竹，打算讲的内容要能打动自己，让自己有种不吐不快之感。当你察觉演讲者发自肺腑地想将自己内心所思所想与你分享时，难道你还能不为之所吸引吗？</p></blockquote><blockquote><p>📌 演讲准备是不是指把一些华丽优美的辞藻拼凑在一起，然后写下来或者背下来？绝非如此。那么是不是把一些连你自己都觉得都言之无物的想法杂糅一下就叫准备呢？也不是。你要做的准备是把自己的想法、观点、论断以及期望结合起来。你生命中的每一天都会与之不期而遇，甚至在你入睡后它们也会出现。生活处处都是感悟和体验，它们深埋于你的潜意识中，就像鹅卵石一般铺满了整个海滩，取之不尽用之不竭。所谓准备，其实是在深思熟虑后，把最吸引你的那些片段抛光、打磨一番，最后组合成一幅属于你的画卷。</p></blockquote>',10)])])}const b=o(l,[["render",r]]);export{u as __pageData,b as default};
